export interface Rud1LogoProps extends Omit<React.SVGProps<SVGSVGElement>, "height"> {
  variant?: Rud1Variant;
  /** Altura en píxeles; el ancho sale de la proporción. */
  height?: number;
  theme?: "light" | "dark";
  /** "brand" usa la paleta; "mono" pinta todo en currentColor. */
  tone?: "brand" | "mono";
  title?: string;
}

export function Rud1Logo({
  variant = "horizontal",
  height = 32,
  theme = "light",
  tone = "brand",
  title = "rud1",
  ...rest
}: Rud1LogoProps) {
  const art = tone === "mono" ? MONO[variant] : ART[variant][theme];
  return (
    <svg
      viewBox={art.viewBox}
      height={height}
      width={height * art.ratio}
      role="img"
      aria-label={title}
      {...rest}
    >
      <title>{title}</title>
      {art.paths}
    </svg>
  );
}

export default Rud1Logo;
